function epUrl(code) {
    const h = code[0], g = code[1];
    if (h === 9 || !HOSTS[h]) return String(g);
    return HOSTS[h] + TPL.replace("{guid}", g);
}

function card(r) {
    return { vod_id: "vod/" + r.id, vod_name: r.name, vod_remarks: r.remark, style: { type: "rect", ratio: 0.75 } };
}

function detailVod(r) {
    const item = card(r);
    Object.assign(item, {
        vod_play_from: "央视网",
        vod_content: r.name + "（央视网）" + r.remark,
        vod_play_url: r.eps.map(function (e, i) {
            const nm = e[0] || "";
            return "第" + (i + 1) + "集" + (nm ? " " + nm : "") + "$" + epUrl([e[1], e[2]]);
        }).join("#"),
    });
    return item;
}

function findRecord(id) { return CATALOG.find(function (r) { return r.id === String(id).replace(/^vod\//, ""); }); }

export default class CctvDrama extends Spider {
    homeContent(filter) {
        return { class: [{ type_id: "all", type_name: "全部" }] };
    }
    homeVideoContent() { return { list: CATALOG.map(card) }; }
    categoryContent(tid, pg, filter, extend) {
        return page(CATALOG.map(card), pg || "1", PAGE_SIZE);
    }
    searchContent(key, quick, pg) {
        const q = String(key || "").trim().toLowerCase();
        if (!q) return page([], pg || "1", PAGE_SIZE);
        const items = CATALOG.filter(function (r) { return String(r.name).toLowerCase().includes(q); });
        return page(items.map(card), pg || "1", PAGE_SIZE);
    }
    detailContent(ids) {
        const list = [];
        for (const id of ids) { const r = findRecord(id); if (r) list.push(detailVod(r)); }
        return { list: list };
    }
    playerContent(flag, id, vipFlags) {
        const url = String(id || "").trim();
        if (!/^https?:\/\//i.test(url)) return { parse: 0, msg: "无效播放地址" };
        return { parse: 0, jx: 0, url: url, header: "" };
    }
}
